// === Tab: mySketch ===
/**
 * Attrattore di Peter de Jong con sovrimpressione della formula e parametri.
 * Premi 's' (o 'S') per salvare il canvas come immagine.
 */

// Parametri dell'attrattore
let a = -2.36888;
let b = -2.1;
let c = -2.5;
let d = -2.0;

// Coordinate iniziali
let x = 0.0;
let y = 0.0;

// Parametri di disegno
let scaleFactor = 120;   
let pointsPerFrame = 8000;
let max_cycle=100;
let t=0;

function setup() {
  createCanvas(800, 800);
  background(120);

  frameRate(30);
	pixelDensity(8)

  fill(0)
	rect(0,0,800,800)
}

function draw() {
  // ---- Disegno dei punti dell'attrattore ----
  // Trasliamo il sistema di coordinate al centro del canvas
  push();
  translate(width / 2, height / 2);

  // Iteriamo un certo numero di punti per "riempire" gradualmente la forma
  for (let i = 0; i < pointsPerFrame; i++) {
    // Calcoliamo le coordinate successive
    let xNext = sin(a * y) - cos(b * x);
    let yNext = sin(c * x) - cos(d * y);

    // Aggiorniamo x e y
    x = xNext;
    y = yNext;

    // Impostiamo un colore in base a x (o a un mix di x,y)
    //let col = map(x, -2, 2, 0, 255);
    //let col2 = map(y, -2, 2, 100, 255);
    //stroke(col, col2, col2, 20);
    stroke(220,220,220,40)
    point(x * scaleFactor, y * scaleFactor);
  }
  pop();

  push();
  noStroke();

  // Rettangolo semi-trasparente dietro il testo (per leggibilità)
  fill(0, 150);
  //rect(10, 10, 250, 10);

  fill(255);
  textSize(14);
  text(
    "Peter de Jong Attractor\n" +
    "x_{n+1} = sin(a*y_n) - cos(b*x_n)\n" +
    "y_{n+1} = sin(c*x_n) - cos(d*y_n)\n" +
    "a=" + a + ", b=" + b + ", c=" + c + ", d=" + d,
    20,
    30
  );
  pop();

  t++;
  if(t>=max_cycle)
    noLoop();

}

// Funzione per salvare l'immagine premendo il tasto 's' o 'S'
function keyPressed() {
  if (key === 's' || key === 'S') {
    saveCanvas('peter_de_jong', 'png');
  }
}

